<script setup lang="ts">
import { ArrowUpRight, Boxes, CreditCard, Plus, X } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi()
const { data, refresh } = await useAsyncData('partner-overview', () => api.request<any>('/portal/partner/overview').catch(() => null))
const open = ref(false); const saving = ref(false)
const form = reactive({ name: '', category: 'Inspection pigs', description: '', priceUsd: 0, stock: 1, leadTime: '3–5 weeks', image: 'six-inch-pig' })
async function create() { saving.value = true; try { await api.request('/portal/partner/products', { method: 'POST', body: form }); open.value = false; await refresh() } finally { saving.value = false } }
async function toggle(product: any) { await api.request(`/portal/partner/products/${product._id}`, { method: 'POST', body: { active: !product.active } }); await refresh() }
</script>
<template>
  <div><PortalHeader><template #eyebrow>Manufacturer workspace</template><template #title>Partner catalog.</template><template #subtitle>List products, manage inventory and publish directly into the Vomtek marketplace.</template><template #actions><button class="btn btn-dark !min-h-9 !px-3 !text-[10px]" @click="open=true"><Plus :size="13"/> Add product</button></template></PortalHeader>
    <div class="grid gap-4 lg:grid-cols-3"><div class="rounded-xl bg-ink p-5 text-bone"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-mint">Partner status</p><p class="mt-2 font-display text-[27px]">{{ data?.partner?.status || 'pending' }}</p><p class="mt-1 text-[11px] text-bone/45">{{ data?.partner?.plan }} plan · {{ data?.partner?.monthlyFee ? money(data.partner.monthlyFee) + '/mo' : 'no fee' }}</p></div><div class="rounded-xl border border-ink/12 bg-bone p-5"><p class="flex items-center gap-2 font-mono text-[8px] uppercase tracking-[.08em] text-ink/35"><Boxes :size="13"/> Listings</p><p class="mt-2 font-display text-[27px]">{{ data?.products?.length || 0 }}</p><p class="mt-1 text-[11px] text-ink/45">Published marketplace SKUs</p></div><div class="rounded-xl border border-ink/12 bg-bone p-5"><p class="flex items-center gap-2 font-mono text-[8px] uppercase tracking-[.08em] text-ink/35"><CreditCard :size="13"/> Billing</p><p class="mt-2 font-display text-[27px]">{{ money(data?.partner?.monthlyFee || 0) }}</p><p class="mt-1 text-[11px] text-ink/45">Monthly partner subscription</p></div></div>
    <div class="mt-5 overflow-hidden rounded-xl border border-ink/12 bg-bone"><div class="flex items-center justify-between border-b border-ink/10 px-4 py-3"><p class="font-display text-[18px]">My products</p><span class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">Vendor: {{ data?.org?.name }}</span></div><div class="divide-y divide-ink/10"><div v-for="p in data?.products || []" :key="p._id" class="grid gap-3 px-4 py-3 md:grid-cols-[1fr_120px_100px_100px_auto] md:items-center"><div class="min-w-0"><p class="truncate text-[12px] font-medium">{{ p.name }}</p><p class="font-mono text-[8px] text-ink/35">{{ p.sku }} · {{ p.category }}</p></div><span class="font-mono text-[11px]">{{ money(p.priceUsd) }}</span><span class="text-[11px]">{{ p.stock }} in stock</span><StatusPill :status="p.active ? 'active' : 'draft'" /><button class="font-mono text-[8px] uppercase tracking-[.06em] text-signal-deep" @click="toggle(p)">{{ p.active ? 'Unpublish' : 'Publish' }}</button></div></div><div v-if="!data?.products?.length" class="p-8 text-center text-[12px] text-ink/40">No products yet. Add the first one.</div></div>
    <div v-if="open" class="fixed inset-0 z-[70] flex items-start justify-center overflow-y-auto bg-ink/45 p-4 backdrop-blur-sm md:items-center" @click.self="open=false"><div class="w-full max-w-lg rounded-2xl bg-bone p-6"><div class="flex items-start justify-between"><div><p class="label-mono text-signal-deep">New listing</p><h2 class="mt-1 font-display text-[26px]">Publish a product.</h2></div><button @click="open=false"><X :size="18"/></button></div><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="create"><div class="sm:col-span-2"><label class="field-label">Product name</label><input v-model="form.name" required class="field"></div><div><label class="field-label">Category</label><AppSelect v-model="form.category" :options="['Inspection pigs','Cleaning pigs','Spares','Instrumentation','Rentals']" placeholder="Select category" aria-label="Product category" /></div><div><label class="field-label">Price (USD)</label><input v-model.number="form.priceUsd" type="number" class="field"></div><div><label class="field-label">Stock</label><input v-model.number="form.stock" type="number" class="field"></div><div><label class="field-label">Lead time</label><input v-model="form.leadTime" class="field"></div><div class="sm:col-span-2"><label class="field-label">Description</label><textarea v-model="form.description" rows="3" class="field resize-none"/></div><div class="sm:col-span-2 flex justify-end gap-2"><button type="button" class="btn btn-outline" @click="open=false">Cancel</button><button class="btn btn-dark" :disabled="saving">{{ saving ? 'Publishing…' : 'Publish' }}</button></div></form></div></div>
  </div>
</template>
